func (q *Queries) ListBond(ctx context.Context, arg ListBondParams) ([]ListBondRow, error) {
	rows, err := q.db.Query(ctx, listBond,
		arg.ScopeClientID,
		arg.Q,
		arg.BondTypeID,
		arg.RatingID,
		arg.SectorID,
		arg.ClientID,
		arg.ParentBondID,
		arg.EmitentID,
		arg.BondPeriodeOptionID,
		arg.Sort,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListBondRow{}
	for rows.Next() {
		var i ListBondRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.BondName,
			&i.BondCode,
			&i.BondTypeID,
			&i.Description,
			&i.Coupon,
			&i.CouponPaymentPeriode,
			&i.MaturityDate,
			&i.CouponFrequency,
			&i.LastCouponDate,
			&i.BondPrice,
			&i.YieldToMaturity,
			&i.RatingID,
			&i.SectorID,
			&i.BondClassificationID,
			&i.IssuanceDate,
			&i.ClientID,
			&i.NextCouponDate,
			&i.BondStatus,
			&i.BondDurationDays,
			&i.DefaultTransactionFee,
			&i.TotalCoupon,
			&i.TotalFund,
			&i.TotalMaturedValue,
			&i.TotalPaidCoupon,
			&i.TotalPaidFee,
			&i.TotalRevolvingValue,
			&i.TotalTransactionFee,
			&i.NoAktaPengakuanUtang,
			&i.NoAktaPerjanjianPenerbitan,
			&i.TanggalAktaPengakuanUtang,
			&i.TanggalAktaPerjanjianPenerbitan,
			&i.ParentBondID,
			&i.CouponType,
			&i.Arranger,
			&i.AssetAppraisal,
			&i.FeasibilityConsultant,
			&i.FinancialConsultant,
			&i.LegalCounselName,
			&i.MonitoringAgent,
			&i.NotaryName,
			&i.PaymentAgent,
			&i.PublicAccountant,
			&i.SafeKeepingAgent,
			&i.SellingAgent,
			&i.BondSeriesDurationDays,
			&i.NotaryLocation,
			&i.BondShortName,
			&i.MinimumDenomination,
			&i.BookBuildingEndDate,
			&i.BookBuildingStartDate,
			&i.LatestCertificateCounter,
			&i.EmitentID,
			&i.EmitentName,
			&i.BondSeriesNumber,
			&i.BondPeriodeOptionID,
			&i.BondActivateSyncStatus,
			&i.BondExpireSyncStatus,
			&i.BondOfferingSyncStatus,
			&i.RemoteProductID,
			&i.NoAktaPersonalGuarantee,
			&i.TanggalAktaPersonalGuarantee,
			&i.BondTypeUuid,
			&i.BondTypeName,
			&i.BondTypeCode,
			&i.RatingUuid,
			&i.RatingName,
			&i.RatingCode,
			&i.SectorUuid,
			&i.SectorName,
			&i.SectorCode,
			&i.ClientUuid,
			&i.ClientName,
			&i.ClientCode,
			&i.ParentBondUuid,
			&i.ParentBondName,
			&i.ParentBondCode,
			&i.EmitentUuid,
			&i.BondPeriodeOptionUuid,
			&i.BondPeriodeOptionName,
			&i.BondPeriodeOptionCode,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const softDeleteBond = `-- name: SoftDeleteBond :execrows
UPDATE bond t
SET deleted_at = now(), deleted_by = $1
WHERE t.uuid = $2 AND t.updated_at = $3 AND t.deleted_at IS NULL
`

type SoftDeleteBondParams struct {
	Actor             *string
	Uuid              uuid.UUID
	ExpectedUpdatedAt time.Time
}

func (q *Queries) SoftDeleteBond(ctx context.Context, arg SoftDeleteBondParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteBond, arg.Actor, arg.Uuid, arg.ExpectedUpdatedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

